{
  "name": "fiscais-video",
  "private": true,
  "version": "1.0.0",
  "description": "Vídeo animado da fiscalização do 2º turno de 2026 (16:9 e 9:16), Arvor Intelligence",
  "scripts": {
    "studio": "remotion studio",
    "render:wide": "remotion render FiscaisWide out/fiscais_16x9.mp4",
    "render:vertical": "remotion render FiscaisVertical out/fiscais_9x16.mp4",
    "render": "npm run render:wide && npm run render:vertical",
    "typecheck": "tsc --noEmit",
    "lint": "eslint src"
  },
  "dependencies": {
    "@remotion/cli": "4.0.436",
    "@remotion/google-fonts": "4.0.436",
    "react": "19.1.0",
    "react-dom": "19.1.0",
    "remotion": "4.0.436"
  },
  "devDependencies": {
    "@remotion/eslint-config-flat": "4.0.436",
    "@types/react": "19.1.0",
    "@types/react-dom": "19.1.0",
    "eslint": "9.30.0",
    "typescript": "5.8.3"
  }
}
import voz from "./dados/voz.json";
import type { CenaVoz, Palavra, Voz } from "./tipos";

export const FPS = 30;
/** Silêncio depois de cada cena, em segundos, para a imagem respirar. */
const RESPIRO = 0.9;
/** Cauda final, depois da última frase. */
const CAUDA = 3.0;

export type Cena = CenaVoz & {
  inicio: number;
  frames: number;
};

const VOZ = voz as Voz;

export const CENAS: Cena[] = (() => {
  let cursor = 0;
  return VOZ.cenas.map((c, i) => {
    const ultima = i === VOZ.cenas.length - 1;
    const frames = Math.round((c.segundos + (ultima ? CAUDA : RESPIRO)) * FPS);
    const cena = { ...c, inicio: cursor, frames };
    cursor += frames;
    return cena;
  });
})();

export const TOTAL_FRAMES = CENAS.reduce((soma, c) => soma + c.frames, 0);

export const cenaPorId = (id: string): Cena => {
  const cena = CENAS.find((c) => c.id === id);
  if (!cena) {
    throw new Error(`cena sem narração: ${id}`);
  }
  return cena;
};

const normalizar = (s: string): string =>
  s
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z0-9]/g, "");

/**
 * Quadro (relativo à cena) em que a narração chega a uma palavra. Procura, a partir de
 * `aPartirDe` (índice de palavra), a primeira palavra que começa com `texto`, sem acento
 * nem pontuação. Devolve `null` se não achar: a cena então usa a hipótese de tempo.
 */
export const indiceDa = (palavras: Palavra[], texto: string, aPartirDe = 0): number => {
  const alvo = normalizar(texto);
  for (let i = Math.max(0, aPartirDe); i < palavras.length; i++) {
    if (normalizar(palavras[i].w).startsWith(alvo)) {
      return i;
    }
  }
  return -1;
};

export const quadroDa = (
  palavras: Palavra[],
  texto: string,
  aPartirDe = 0,
): number | null => {
  const i = indiceDa(palavras, texto, aPartirDe);
  return i < 0 ? null : Math.round(palavras[i].t * FPS);
};

/** Mesmo que `quadroDa`, com reserva quando a palavra não aparece. */
export const quadro = (
  palavras: Palavra[],
  texto: string,
  reservaSegundos: number,
  aPartirDe = 0,
): number => quadroDa(palavras, texto, aPartirDe) ?? Math.round(reservaSegundos * FPS);
import { createContext, useContext } from "react";

export type Formato = {
  largura: number;
  altura: number;
  vertical: boolean;
  /** Margem segura horizontal, em px. */
  margem: number;
};

const Contexto = createContext<Formato>({
  largura: 1920,
  altura: 1080,
  vertical: false,
  margem: 96,
});

export const FormatoProvider = Contexto.Provider;

export const useFormato = (): Formato => useContext(Contexto);

export const formatoDe = (largura: number, altura: number): Formato => ({
  largura,
  altura,
  vertical: altura > largura,
  margem: altura > largura ? 56 : 96,
});
export type Nivel = "alta" | "media" | "baixa";

export type Exemplo = {
  uf: string;
  municipio: string;
  zona: number;
  secao: number;
  local: string;
  bairro: string | null;
  aptos: number;
  votantes: number;
  validos: number;
  brancos: number;
  nulos: number;
  lula: number;
  flavio: number;
  lula_pct: number;
  flavio_pct: number;
  zona_lula_pct: number;
  zona_flavio_pct: number;
  uf_lula_pct: number;
  uf_flavio_pct: number;
  encerramento_brasilia: string;
  recebido_tse: string;
  n_cargas: number;
  lula_2022_pct: number | null;
  flavio_2022_pct: number | null;
  criterios: string[];
  nivel: Nivel;
  pontuacao: number;
  explicacao_provavel: string;
  o_que_conferir: string;
  lat: number;
  lon: number;
  local_id: string;
  detalhe: Record<string, unknown> | null;
  detalhes: Record<string, Record<string, unknown>>;
  local_secoes_sinalizadas: number | null;
  local_secoes_total: number | null;
  xy: [number, number];
};

export type Criterio = {
  id: string;
  nome: string;
  mede: string;
  limiar: string;
  peso: number | Record<string, number>;
  secoes: number;
  por_nivel: Record<Nivel, number>;
  explicacao_comum: string;
  o_que_conferir: string;
  exemplo: Exemplo;
};

export type Dados = {
  gerado_em: string;
  fonte: string;
  rotulos: { atipico: string; prioridade: string; resolve: string };
  resumo: {
    secoes_universo: number;
    secoes_sinalizadas: number;
    por_nivel: Record<Nivel, { secoes: number; locais: number; municipios: number }>;
    aptos_sinalizadas: number;
    pct_sinalizadas: number;
    fiscais_um_por_local: { alta: number; alta_media: number; todos: number };
    fiscais_dois_por_secao: { alta: number; alta_media: number; todos: number };
    explicacao_por_codigo: Record<string, number>;
    sem_arquivo: number;
  };
  sem_arquivo_por_zona: { uf: string; municipio: string; zona: number; secoes: number }[];
  zonas_congeladas: { zonas: number; secoes: number; horas_min: number; horas_max: number };
  criterios: Criterio[];
  por_uf: {
    uf: string;
    regiao: string;
    secoes: number;
    alta: number;
    media: number;
    baixa: number;
    locais_alta: number;
    taxa_pct: number;
  }[];
  municipios: {
    uf: string;
    municipio: string;
    secoes: number;
    alta: number;
    media: number;
    pontuacao_soma: number;
  }[];
  contrario: string[];
  mapa: {
    view: number;
    ufs: { uf: string; d: string }[];
    pontos: [number, number, Nivel][];
    pontos_baixa: [number, number][];
  };
};

export type Palavra = { w: string; t: number; f: number };

export type CenaVoz = {
  id: string;
  arquivo: string;
  segundos: number;
  texto: string;
  palavras: Palavra[];
};

export type Voz = { modelo: string; cenas: CenaVoz[] };

